export async function getUsers(){const r=localStorage.getItem("my_users");if(r)return JSON.parse(r);try{const r=await fetch("./data/users.json");if(!r.ok)throw new Error("Kullanıcılar yüklenirken hata oluştu.");const t=await r.json();return localStorage.setItem("my_users",JSON.stringify(t)),t}catch(r){return console.error("userService Hata:",r),[]}}export async function getUserById(r){return(await getUsers()).find(t=>String(t.userId||t.id)===String(r))}export function saveUsersToStorage(r){r&&localStorage.setItem("my_users",JSON.stringify(r))}